# Okabe–Ito
BLUE, ORANGE, GREEN, VERMILION, SKY, YELLOW, PURPLE = (
    "#0072B2", "#E69F00", "#009E73", "#D55E00", "#56B4E9", "#F0E442", "#CC79A7")
INK, INK2, GHOST = "#111111", "#555555", "#bbbbbb"
PALE_GREEN = "#7fcfb9"  # Okabe–Ito green lightened halfway to white, for a filled true body
DOTS = (0, (0.05, 1.9))  # the true surface over cells: fine round dots (with round caps), points


def style() -> None:
    mpl.rcParams.update({
        "font.family": "serif", "font.size": 8, "axes.linewidth": 0.6, "lines.linewidth": 1.0,
        "hatch.linewidth": 0.5, "savefig.bbox": "tight", "pdf.fonttype": 42,
        "mathtext.fontset": "dejavuserif",
    })


def bare(ax: plt.Axes) -> None:
    ax.set_aspect("equal")
    ax.set_xticks([])
    ax.set_yticks([])
    for s in ax.spines.values():
        s.set_visible(False)


# ------------------------------------------------------------------ 2-D clipping

def clip_poly(poly: np.ndarray, a: np.ndarray, b: np.ndarray) -> np.ndarray:
    """Sutherland–Hodgman: keep the part of `poly` left of the directed line a→b."""
    out = []
    n = len(poly)
    side = lambda p: (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])  # noqa: E731
    for i in range(n):
        p, q = poly[i], poly[(i + 1) % n]
        sp, sq = side(p), side(q)
        if sp >= 0:
            out.append(p)
        if (sp >= 0) != (sq >= 0):
            t = sp / (sp - sq)
            out.append(p + t * (q - p))
    return np.array(out)


def clip_convex(cell: np.ndarray, body: np.ndarray) -> np.ndarray:
    poly = cell
    for i in range(len(body)):
        if len(poly) == 0:
            break
        poly = clip_poly(poly, body[i], body[(i + 1) % len(body)])
    return poly


def area(poly: np.ndarray) -> float:
    if len(poly) < 3:
        return 0.0
    x, y = poly[:, 0], poly[:, 1]
    return 0.5 * float(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))


def centroid(poly: np.ndarray) -> np.ndarray:
    x, y = poly[:, 0], poly[:, 1]
    cr = x * np.roll(y, -1) - np.roll(x, -1) * y
    a = 0.5 * cr.sum()
    return np.array([((x + np.roll(x, -1)) * cr).sum(), ((y + np.roll(y, -1)) * cr).sum()]) / (6 * a)


def second_moment(poly: np.ndarray, c: np.ndarray) -> np.ndarray:
    """∫(x−c)(x−c)ᵀ dA of a polygon, by triangles from c."""
    m = np.zeros((2, 2))
    for i in range(len(poly)):
        p, q = poly[i] - c, poly[(i + 1) % len(poly)] - c
        a = 0.5 * (p[0] * q[1] - p[1] * q[0])
        m += a / 6.0 * (np.outer(p, p) + np.outer(q, q) + 0.5 * (np.outer(p, q) + np.outer(q, p)))
    return m


def rot2(t: float) -> np.ndarray:
    return np.array([[np.cos(t), -np.sin(t)], [np.sin(t), np.cos(t)]])


# ------------------------------------------------------------------ a

def inside_convex(pt: np.ndarray, body: np.ndarray) -> bool:
    """Whether a point is inside an anticlockwise convex polygon."""
    for i in range(len(body)):
        a, b = body[i], body[(i + 1) % len(body)]
        if (b[0] - a[0]) * (pt[1] - a[1]) - (b[1] - a[1]) * (pt[0] - a[0]) < 0:
            return False
    return True


PYR_PITCH = 0.11  # m
PYR_BASE, PYR_HEIGHT = 13 * PYR_PITCH, 1.1  # m: an odd number of cells wide, so the apex is one cell
PYR_ELEV, PYR_AZIM = 24, -40  # the 3-D row's view, degrees


VIEW = lit.View(PYR_ELEV, PYR_AZIM)


def toward_eye(normals: np.ndarray) -> np.ndarray:
    """Which faces face the viewer."""
    return VIEW.facing(normals)


def pyramid_faces() -> list[np.ndarray]:
    """A square-based pyramid on the lattice axes, centroid at the origin: outward anticlockwise faces."""
    b, z0 = PYR_BASE / 2, -PYR_HEIGHT / 4  # a pyramid's centroid is a quarter of the way up
    base = [np.array([x, y, z0]) for x, y in ((-b, -b), (b, -b), (b, b), (-b, b))]
    apex = np.array([0.0, 0.0, z0 + PYR_HEIGHT])
    return [np.array(base[::-1])] + [np.array([base[i], base[(i + 1) % 4], apex]) for i in range(4)]


def pyramid_cells(h: float, off: np.ndarray) -> tuple[np.ndarray, list[tuple[np.ndarray, list]]]:
    """The interior cell centres, and each boundary cell's centre with its clipped piece's faces.

    The same classification and clipper as the benchmark (`skin_bench.lattice`), kept per piece
    as polygons so each piece can be drawn with its own edges.
    """
    faces = pyramid_faces()
    tris = skin_bench.fan(faces, 1.0)
    pn, pd = skin_bench.planes_of(tris)
    verts = tris.reshape(-1, 3)
    lo = np.floor((verts.min(0) - off) / h).astype(int)
    hi = np.floor((verts.max(0) - off) / h).astype(int)
    g = np.stack(np.meshgrid(*[np.arange(lo[i], hi[i] + 1) for i in range(3)], indexing="ij"),
                 -1).reshape(-1, 3)
    centres = off + (g + 0.5) * h
    sup = 0.5 * h * np.abs(pn).sum(1)
    dist = centres @ pn.T - pd
    inner = centres[np.all(dist + sup <= 0, axis=1)]
    cube0 = list(skin_bench.cube_quads(np.zeros((1, 3)), h))
    pieces = []
    for c, d in zip(centres, dist):
        if np.any(d - sup >= 0) or np.all(d + sup <= 0):
            continue  # outside, or a whole interior cube
        piece = [q + c for q in cube0]
        for p in np.argsort(-d):
            if d[p] + sup[p] > 0:
                piece = skin_bench.clip(piece, pn[p], float(pd[p]), h)
                if not piece:
                    break
        if piece:
            pieces.append((c, piece))
    return inner, pieces


def fig_representations() -> None:
    fig = plt.figure(figsize=(6.8, 4.6))
    # the 2-D row: the pyramid's cross-section on 17 x 17 cells, one cell centred on the origin;
    # the triangle is 13 cells wide and 13 high, base and apex on grid lines, centred on the paper
    h, n = 0.5, 17
    g0 = -n * h / 2
    body = np.array([[-6.5, -6.5], [6.5, -6.5], [0.0, 6.5]]) * h
    cells = [(i, j) for i in range(n) for j in range(n)]
    titles = ["true surface", "plain cubes (staircase)", "interior cubes + clipped pieces"]
    for k in range(3):
        ax = fig.add_axes((0.035 + 0.33 * k, 0.53, 0.30, 0.41))  # the 2-D row, square panels
        bare(ax)
        for i, j in cells:
            ax.add_patch(Rectangle((g0 + i * h, g0 + j * h), h, h, fill=False, ec=GHOST, lw=0.3))
        if k == 0:
            ax.add_patch(Polygon(body, fc=PALE_GREEN, ec=GREEN, lw=1.2))
        else:
            for i, j in cells:
                sq = np.array([[i, j], [i + 1, j], [i + 1, j + 1], [i, j + 1]], float) * h + g0
                piece = clip_convex(sq, body)
                a = area(piece) if len(piece) >= 3 else 0.0
                full = abs(a - h * h) < 1e-9
                if k == 1:
                    if inside_convex((np.array([i, j]) + 0.5) * h + g0, body):
                        ax.add_patch(Rectangle((g0 + i * h, g0 + j * h), h, h, fc=SKY, ec=BLUE, lw=0.4))
                elif full:
                    ax.add_patch(Rectangle((g0 + i * h, g0 + j * h), h, h, fc=SKY, ec=BLUE, lw=0.4))
                elif a > 1e-9:
                    ax.add_patch(Polygon(piece, fc=ORANGE, ec=VERMILION, lw=0.4, hatch="////"))
            ax.add_patch(Polygon(body, fill=False, ec=INK, lw=1.0, ls=DOTS, capstyle="round"))
        ax.set_xlim(g0, -g0)
        ax.set_ylim(g0, -g0)
        ax.set_title(f"({'abc'[k]}) {titles[k]}", fontsize=8)
    # 3-D row: a square-based pyramid on the lattice's axes, cut by the benchmark's clipper.
    # (f) draws the whole body as its clipped pieces.
    # cells centred on the axis, base on a lattice plane
    h3, off = PYR_PITCH, np.array([-PYR_PITCH / 2, -PYR_PITCH / 2, -PYR_HEIGHT / 4])
    inner, pieces = pyramid_cells(h3, off)

    faces = pyramid_faces()
    tris = skin_bench.fan(faces, 1.0)
    pn, pd = skin_bench.planes_of(tris)
    z0 = faces[0][0, 2]
    # a faint contact shadow on the ground under the body, and the ground as an occluder for the
    # faces' ambient occlusion (the pyramid is convex, so nothing else occludes it)
    ground = np.array([[[-9, -9, z0], [9, -9, z0], [9, 9, z0]], [[-9, -9, z0], [9, 9, z0], [-9, 9, z0]]])
    occluders = np.concatenate([tris, ground])
    ao_r = 0.4  # m, the occlusion's reach
    lo = np.floor((tris.reshape(-1, 3).min(0) - off) / h3).astype(int)
    hi = np.floor((tris.reshape(-1, 3).max(0) - off) / h3).astype(int)
    g = np.stack(np.meshgrid(*[np.arange(lo[i], hi[i] + 1) for i in range(3)], indexing="ij"),
                 -1).reshape(-1, 3)
    keep = g[np.all((off + (g + 0.5) * h3) @ pn.T - pd <= 0, axis=1)]
    occ = np.zeros(tuple(hi - lo + 1), dtype=bool)
    occ[tuple((keep - lo).T)] = True

    def solid(ijk: np.ndarray) -> np.ndarray:
        """Plain-cube occupancy; the ground (below the base) counts as solid for the AO."""
        q = ijk - lo
        ok = np.all((q >= 0) & (q < occ.shape), axis=1)
        out = ijk[:, 2] < 0
        out[ok] = occ[tuple(q[ok].T)]
        return out

    def above_ground(ijk: np.ndarray) -> np.ndarray:
        return solid(ijk) & (ijk[:, 2] >= 0)

    edges = [np.array([f[i], f[i + 1]]) for f in faces[1:] for i in range(2)]  # base, then lateral
    # the panels' extent: the base with a margin for the contact shadow, and the apex (plus the
    # plain cubes' top cell), so the pyramid fills its panel
    bound = np.array([[x, y, z0] for x in (-PYR_BASE / 2 - 0.1, PYR_BASE / 2 + 0.1)
                      for y in (-PYR_BASE / 2 - 0.1, PYR_BASE / 2 + 0.1)]
                     + [[0.0, 0.0, z0 + PYR_HEIGHT + 0.12]])
    for k in range(3):
        ax = fig.add_axes((0.035 + 0.33 * k, 0.10, 0.30, 0.36))  # the 3-D row, about as large
        sc = lit.Scene(VIEW)
        sc.add_ground(np.array([0.0, 0.0, z0]), PYR_BASE / 2 + 0.45, tris, ao_r, n=40)
        if k == 0:
            for f in faces:
                if not VIEW.facing(lit.normal(f)):
                    continue
                parts = lit.split_polygon(f, 4)
                ctr = np.array([t.mean(axis=0) for t in parts])
                ao = lit.ray_occlusion(ctr, np.tile(lit.normal(f), (len(ctr), 1)), occluders, ao_r,
                                         n_rays=160)
                sc.add_shaded(f, parts, ao, PALE_GREEN, edge=GREEN, lw=0.6)
        elif k == 1:
            lit.add_voxels(sc, keep, off, h3, solid, [SKY] * len(keep), [BLUE] * len(keep), 0.15)
            sc.wireframe(edges, lit.occluded_by_cells(VIEW, above_ground, off, h3, 2.0),
                         lit.behind_cells(VIEW, above_ground, off, h3, 2.0))
        else:
            # the whole body as its clipped pieces: each piece's share of the pyramid's surface,
            # outlined, so the lattice shows where it cuts the faces (the interior cubes are hidden
            # inside; drawing the pieces' cell walls as well only adds clutter)
            on = [(f, np.all(np.abs(f @ pn.T - pd) < 1e-9, axis=0)) for _, fs in pieces for f in fs]
            front = toward_eye(pn)
            outer = [f for f, plane in on if np.any(plane & front)]
            ctr = np.array([f.mean(axis=0) for f in outer])
            nrm = np.array([lit.normal(f) for f in outer])
            ao = lit.ray_occlusion(ctr, nrm, occluders, ao_r)
            for f, a in zip(outer, ao):
                sc.add_shaded(f, [f], np.array([a]), ORANGE, edge=VERMILION, lw=0.25)
            sc.wireframe(edges, lit.occluded_by_tris(VIEW, tris, 1e-4))
        sc.draw(ax, bound)
        ax.set_anchor("N")  # the pyramid just under its title
        ax.set_title(f"({'def'[k]})", fontsize=8)
    # The key is in the paper's caption, at print size (referee, layout item 3); the counts are
    # printed here for it.
    print(f"diag-representations: (f) {len(pieces)} clipped pieces, {len(inner)} whole cubes inside")
    fig.savefig(FIG / "diag-representations.pdf")
    plt.close(fig)


def lat_off() -> np.ndarray:
    return np.array([0.05, 0.11, 0.07])


# ------------------------------------------------------------------ b

def fig_fill_moments() -> None:
    fig, axes = plt.subplots(1, 3, figsize=(6.8, 2.4))
    # a surface (line) crossing a row of three cells; the body is below the line
    a, b = np.array([0.0, -0.2]), np.array([3.0, 1.2])

    def cut(i: int) -> np.ndarray:
        sq = np.array([[i, 0], [i + 1, 0], [i + 1, 1], [i, 1]], float)
        return clip_poly(sq, b, a)  # keep the side below the line

    titles = ["(a) fill fraction $f$", "(b) mass at the centroid $\\bar{\\mathbf{c}}$",
              "(c) + second moment $I$"]
    notes = ["shade and number:\nhow full each cell is", "+ cell centre\n\u25cf centroid of the filled part",
             "ellipse: the filled part's\nsecond moment"]
    for k, ax in enumerate(axes):
        bare(ax)
        for i in range(3):
            ax.add_patch(Rectangle((i, 0), 1, 1, fill=False, ec=INK2, lw=0.6))
            piece = cut(i)
            f = area(piece)
            shade = mpl.colors.to_rgba(BLUE, 0.15 + 0.75 * f)
            ax.add_patch(Polygon(piece, fc=shade if k == 0 else mpl.colors.to_rgba(SKY, 0.6),
                                 ec=BLUE, lw=0.6))
            cc = np.array([i + 0.5, 0.5])
            if k == 0:
                ax.text(i + 0.5, 1.07, f"{f:.2f}", ha="center", fontsize=7.5)
            if k >= 1:
                c = centroid(piece)
                ax.plot(*cc, marker="+", color=INK2, ms=7, mew=0.9)
                ax.plot(*c, marker="o", color=VERMILION, ms=4)
                ax.annotate("", xy=c, xytext=cc,
                            arrowprops=dict(arrowstyle="->", color=VERMILION, lw=0.7))
            if k == 2:
                c = centroid(piece)
                m = second_moment(piece, c) / area(piece)
                w, v = np.linalg.eigh(m)
                ang = np.degrees(np.arctan2(v[1, 1], v[0, 1]))
                ax.add_patch(Ellipse(c, 2 * np.sqrt(w[1]), 2 * np.sqrt(w[0]), angle=ang,
                                     fill=False, ec=PURPLE, lw=1.0, ls="-"))
        ax.plot([a[0], b[0]], [a[1], b[1]], color=INK, lw=1.0, ls=DOTS, dash_capstyle="round")
        ax.set_xlim(-0.15, 3.15)
        ax.set_ylim(-0.12, 1.25)
        ax.set_title(titles[k], fontsize=8)
        ax.text(1.5, -0.1, notes[k], ha="center", fontsize=6.5, va="top")
    fig.savefig(FIG / "diag-fill-moments.pdf")
    plt.close(fig)


# ------------------------------------------------------------------ c

def cube_faces() -> list[np.ndarray]:
    return [q for q in skin_bench.cube_quads(np.zeros((1, 3)), 1.0)]


def clip_cube(planes: list[tuple[np.ndarray, float]]) -> list[np.ndarray]:
    faces = cube_faces()
    for n, d in planes:
        n = n / np.linalg.norm(n)
        faces = skin_bench.clip(faces, n, d / 1.0, 1.0)
        if not faces:
            break
    return faces


def unique_edges(faces: list[np.ndarray]) -> list[np.ndarray]:
    """Each polygon edge once (edges shared by neighbouring faces merged), as (2, 3) arrays."""
    seen: dict[tuple, np.ndarray] = {}
    for f in faces:
        for i in range(len(f)):
            a, b = f[i], f[(i + 1) % len(f)]
            if np.linalg.norm(b - a) < 1e-9:
                continue
            key = tuple(sorted([tuple(np.round(a, 6)), tuple(np.round(b, 6))]))
            seen.setdefault(key, np.array([a, b]))
    return list(seen.values())


def notched_cell(m: np.ndarray, d: float) -> list[np.ndarray]:
    """The unit cell keeping m·x ≤ d or m'·x ≤ d, m' = m mirrored in x (two mesh faces meeting
    at a ridge, both planes containing the y axis): a prism along y, as its outward faces.

    Built directly rather than as the union of two convex pieces, so no face is split in two and
    no edge is drawn inside a flat face. Each face starts at a vertex that sees all of it (the
    notch's apex for the end caps), so a fan from its first vertex covers it.
    """
    za = d / m[2]                          # the apex, on x = 0
    xt = (d - 0.5 * m[2]) / m[0]           # where the plane m meets the top, z = 0.5
    sec = np.array([[0.0, za], [xt, 0.5], [-0.5, 0.5], [-0.5, -0.5], [0.5, -0.5], [0.5, 0.5],
                    [-xt, 0.5]])           # (x, z), anticlockwise, apex first
    faces = []
    for y, out in ((-0.5, -1.0), (0.5, 1.0)):
        cap = np.column_stack([sec[:, 0], np.full(len(sec), y), sec[:, 1]])
        faces.append(cap if lit.normal(cap)[1] * out > 0 else np.vstack([cap[:1], cap[:0:-1]]))
    for i in range(len(sec)):
        (x0, z0), (x1, z1) = sec[i], sec[(i + 1) % len(sec)]
        q = np.array([[x0, -0.5, z0], [x1, -0.5, z1], [x1, 0.5, z1], [x0, 0.5, z0]])
        outward = np.array([z1 - z0, 0.0, x0 - x1])
        faces.append(q if lit.normal(q) @ outward > 0 else q[::-1])
    return faces


CUTS_VIEW = lit.View(20, -60)


def fig_cuts() -> None:
    fig = plt.figure(figsize=(6.8, 3.0))
    u = lambda *v: np.array(v, float)  # noqa: E731
    view = CUTS_VIEW
    cases = [
        ("corner cut: tetrahedron removed", [(u(1, 1, 1), 0.5)]),
        ("corner cut: tetrahedron kept", [(u(-1, -1, -1), -0.5)]),
        ("edge cut: a wedge (prism) kept", [(u(-1, -1, 0), -0.25)]),
        ("face-parallel cut: a slab", [(u(0, 0, 1), -0.2)]),
        ("oblique cut: hexagonal section", [(u(1, 1, 1), 0.0)]),
        ("two planes (a mesh edge): non-convex", None),
    ]
    box = np.array([[x, y, z] for x in (-0.5, 0.5) for y in (-0.5, 0.5) for z in (-0.5, 0.5)])
    for k, (title, planes) in enumerate(cases):
        ax = fig.add_subplot(2, 3, k + 1)
        sc = lit.Scene(view)
        if planes is not None:
            kept = clip_cube(planes)
            gone = clip_cube([(-n, -d) for n, d in planes])
        else:
            n1, n2 = u(1, 0, 0.8), u(-1, 0, 0.8)
            gone = clip_cube([(-n1, -0.1), (-n2, -0.1)])
            kept = notched_cell(n1 / np.linalg.norm(n1), 0.1)
        tris = skin_bench.fan(kept, 1.0)
        # the removed part, faint and behind the kept piece (translucent, so its order does not
        # matter); then the kept piece face by face, lit, with AO from its own geometry (only the
        # non-convex piece has any)
        for f in gone:
            if view.facing(lit.normal(f)):
                sc.add_face(f, GHOST, alpha=0.12, depth=-1e3)
        for f in kept:
            nrm = lit.normal(f)
            if not view.facing(nrm):
                continue
            parts = lit.split_polygon(f, 3)
            ctr = np.array([t.mean(axis=0) for t in parts])
            ao = lit.ray_occlusion(ctr, np.tile(nrm, (len(ctr), 1)), tris, 0.6, n_rays=96)
            sc.add_shaded(f, parts, ao, ORANGE)
        # outlines as exact hidden-line drawings: the cell's and the removed part's edges grey,
        # the piece's black, each only where the kept piece does not hide it
        hide = lit.occluded_by_tris(view, tris, 1e-4)
        sc.edges(unique_edges(cube_faces() + gone), hide, 0.005, color=GHOST, lw=0.4, zorder=3)
        sc.edges(unique_edges(kept), hide, 0.005, color=INK, lw=0.5, zorder=4)
        if k == 4:
            # label one face and one edge the way the closed form uses them
            f = max(kept, key=lambda q: np.dot(skin_bench_normal(q), u(1, 1, 1)))
            cen = f.mean(axis=0)
            nrm = skin_bench_normal(f)
            i0 = max(range(len(f)), key=lambda i: np.linalg.norm(f[(i + 1) % len(f)] - f[i]))
            e0, e1 = f[i0], f[(i0 + 1) % len(f)]
            sc.add_lines([np.array([e0, e1])], color=VERMILION, lw=2.0, zorder=5)
        sc.draw(ax, box * 1.08)
        if k == 4:
            p0, p1 = view.project(cen), view.project(cen + 0.45 * nrm)
            ax.annotate("", xy=p1, xytext=p0, zorder=6,
                        arrowprops=dict(arrowstyle="-|>", color=BLUE, lw=1.0, mutation_scale=6))
            ax.text(*view.project(cen + 0.5 * nrm), r"$\hat{\mathbf{n}}_f$", color=BLUE, fontsize=8)
            ax.text(*view.project(0.5 * (e0 + e1) + u(0, 0, -0.18)), "$e$", color=VERMILION,
                    fontsize=8)
        ax.set_title(title, fontsize=7)
    # The key (orange piece, grey removed part) is in the paper's caption, at print size.
    fig.savefig(FIG / "diag-cuts.pdf")
    plt.close(fig)


def skin_bench_normal(face: np.ndarray) -> np.ndarray:
    n = np.cross(face[1] - face[0], face[2] - face[0])
    return n / np.linalg.norm(n)


# ------------------------------------------------------------------ d

def fig_closed_form() -> None:
    fig = plt.figure(figsize=(6.8, 2.9))
    # (a) the face from the field point
    ax = fig.add_subplot(1, 2, 1, projection="3d")
    ax.set_axis_off()
    ax.view_init(elev=18, azim=-70)
    v = np.array([[0.0, 0.0, 1.0], [1.4, 0.2, 1.0], [0.5, 1.2, 1.0]])
    p = np.array([0.55, 0.35, 0.0])
    lit_view = lit.View(18, -70)  # one flat face: the shared key/fill/ambient light, no occluder
    ax.add_collection3d(Poly3DCollection(
        [v], fc=(*lit.tint(SKY, lit_view.brightness(lit.normal(v))[0]), 0.7), ec=BLUE, lw=1.0))
    for i, vi in enumerate(v):
        ax.plot(*np.array([p, vi]).T, color=INK2, lw=0.6, ls=":")
        ax.text(*(vi + [0.05, 0.0, 0.05]), f"$\\mathbf{{v}}_{i + 1}$", fontsize=8)
    foot = np.array([p[0], p[1], 1.0])
    ax.plot(*np.array([p, foot]).T, color=VERMILION, lw=1.2)
    ax.text(*(0.5 * (p + foot) + [0.08, 0, 0.12]), "$h_f$", color=VERMILION, fontsize=9)
    cen = v.mean(axis=0)
    ax.quiver(*cen, 0, 0, 0.45, color=BLUE, lw=1.0, arrow_length_ratio=0.25)
    ax.text(*(cen + [0.05, 0, 0.5]), "$\\hat{\\mathbf{n}}_f$", color=BLUE, fontsize=9)
    ax.scatter(*p, color=INK, s=12)
    ax.text(*(p + [0.05, 0, -0.12]), "field point $\\mathbf{p}$", fontsize=8)
    # the solid angle as the face projected on a small sphere about p
    t = np.linspace(0, 1, 30)
    for i in range(3):
        a_, b_ = v[i] - p, v[(i + 1) % 3] - p
        arc = np.array([(1 - s) * a_ + s * b_ for s in t])
        arc = 0.35 * arc / np.linalg.norm(arc, axis=1)[:, None] + p
        ax.plot(*arc.T, color=GREEN, lw=1.2)
    ax.text(*(p + [-0.45, 0.0, 0.3]), "$\\omega_f$", color=GREEN, fontsize=9)
    ax.set_xlim(0, 1.4)
    ax.set_ylim(0, 1.4)
    ax.set_zlim(0, 1.3)
    ax.set_title("(a) a face: height $h_f$ and solid angle $\\omega_f$", fontsize=8)
    # (b) the edge
    ax = fig.add_subplot(1, 2, 2)
    bare(ax)
    a, b = np.array([0.0, 0.0]), np.array([3.0, 0.0])
    q = np.array([1.1, 1.3])
    ax.plot(*np.array([a, b]).T, color=VERMILION, lw=2.2)
    ax.plot(*np.array([q, a]).T, color=INK2, lw=0.8)
    ax.plot(*np.array([q, b]).T, color=INK2, lw=0.8)
    ax.plot([q[0], q[0]], [q[1], 0], color=INK2, lw=0.6, ls=":")
    ax.scatter(*q, color=INK, s=12, zorder=3)
    ax.text(q[0] + 0.05, q[1] + 0.08, "$\\mathbf{p}$", fontsize=9)
    ax.text(0.35, 0.72, "$a$", fontsize=9)
    ax.text(2.15, 0.72, "$b$", fontsize=9)
    ax.text(1.5, -0.22, "edge $e$, length $\\ell$", ha="center", color=VERMILION, fontsize=8)
    ax.text(q[0] + 0.05, 0.45, "$r_0$", fontsize=8, color=INK2)
    ax.text(1.5, -0.62, "$L_e = \\int_0^\\ell dt/r = \\ln\\dfrac{a+b+\\ell}{a+b-\\ell}$", ha="center",
            fontsize=9)
    # Written inline, not as \dfrac: the subscripts of a fraction's denominator are unreadable at
    # print size (referee, draft 4).
    ax.text(1.5, -1.05, "near the edge: $a+b-\\ell = r_0^2/(a-\\ell_1)+r_0^2/(b+\\ell_2)$",
            ha="center", fontsize=9.5)
    ax.set_xlim(-0.3, 3.3)
    ax.set_ylim(-1.3, 1.6)
    ax.set_title("(b) an edge: the logarithm $L_e$", fontsize=8)
    fig.savefig(FIG / "diag-closed-form.pdf")
    plt.close(fig)


# ------------------------------------------------------------------ e

def main() -> None:
    FIG.mkdir(exist_ok=True)
    style()
    fig_representations()
    fig_fill_moments()
    fig_cuts()
    fig_closed_form()


if __name__ == "__main__":
    main()
